namespace BriefBar.Core.Presentation;

/// Each icon's drawings, from Fluent UI System Icons (MIT; windows/THIRD-PARTY-NOTICES.md): SVG paths on a square of
/// their size's units. Fluent draws each icon anew for each size, on that size's pixels, so an icon is sharp at the size
/// it was drawn for and blurs scaled: BriefBar has each at the sizes it shows it, where Fluent has them, all in one style,
/// regular or filled, so that it looks the same at each.
public static class IconPaths
{
    /// The drawing of `icon` that suits `size` pixels best: the one Fluent made at that size, or else the nearest, the
    /// larger of two as near, scaled.
    public static IconPath Of(IconKey icon, double size) =>
        Drawings(icon: icon).MinBy(keySelector: drawing => (Math.Abs(value: drawing.Size - size), -drawing.Size))!;

    /// Every drawing of `icon` BriefBar has: its main one, and the others at the sizes it's also shown.
    public static IReadOnlyList<IconPath> Drawings(IconKey icon) => [Of(icon: icon), .. OtherSizes(icon: icon)];

